import aclib

aclib.RunTapirCommand ('ChangeWindow', {'windowType': 'FloorPlan'})

section = aclib.RunTapirCommand ('CreateSections', {
    'sectionsData': [{
        'startCoordinate': {'x': 0.0, 'y': -2.0},
        'endCoordinate': {'x': 10.0, 'y': -2.0},
        'name': 'Tapir Example Section'
    }]
})['elements'][0]

aclib.PrintJson (aclib.RunTapirCommand ('SetSectionsAndElevationsDetails', {
    'elementsWithDetails': [{
        'elementId': section['elementId'],
        'details': {
            'horizontalRange': 'Limited',
            'verticalRange': 'Limited',
            'verticalRangeMin': 0.5,
            'verticalRangeMax': 2.5,
            'linePenIndex': 5
        }
    }]
}))

detail = aclib.RunTapirCommand ('GetSectionsAndElevationsDetails', {'elements': [section]})['detailsOfElements'][0]
aclib.PrintJson ({key: detail.get (key) for key in ('horizontalRange', 'verticalRange', 'verticalRangeMin', 'verticalRangeMax', 'linePenIndex')})

aclib.RunTapirCommand ('DeleteElements', {'elements': [section]})

"""Creates an Interior Elevation of two segments, shows it on one story only, renames its second
segment and limits that segment's vertical range with SetInteriorElevationsDetails, then reads the
settings back with GetDetailsOfElements.

A segment is chosen by its index in the segments GetDetailsOfElements returns. Deletes the interior
elevation at the end.
"""
import aclib

aclib.RunTapirCommand ('ChangeWindow', {'windowType': 'FloorPlan'})

interiorElevation = aclib.RunTapirCommand ('CreateInteriorElevations', {
    'interiorElevationsData': [{
        'nodeCoordinates': [{'x': 0.0, 'y': -2.0}, {'x': 6.0, 'y': -2.0}, {'x': 6.0, 'y': 2.0}],
        'depth': 1.0,
        'name': 'Tapir Example Interior Elevation'
    }]
})['elements'][0]

aclib.PrintJson (aclib.RunTapirCommand ('SetInteriorElevationsDetails', {
    'interiorElevationsWithDetails': [{
        'elementId': interiorElevation['elementId'],
        'details': {
            'showOnStories': 'OneStory',
            'storyToShowOn': 0,
            'segments': [{
                'segmentIndex': 1,
                'name': 'Tapir Example East Wall',
                'id': 'IE-E',
                'settings': {
                    'verticalRange': 'Limited',
                    'verticalRangeMin': 0.0,
                    'verticalRangeMax': 3.0
                }
            }]
        }
    }]
}))

details = aclib.RunTapirCommand ('GetDetailsOfElements', {'elements': [interiorElevation]})['detailsOfElements'][0]['details']
aclib.PrintJson ({
    'showOnStories': details.get ('showOnStories'),
    'segments': [{
        'name': segment['name'],
        'idStr': segment['idStr'],
        'verticalRange': segment['settings'].get ('verticalRange'),
        'verticalRangeMax': segment['settings'].get ('verticalRangeMax')
    } for segment in details['segments']]
})

aclib.RunTapirCommand ('DeleteElements', {'elements': [interiorElevation]})

"""Creates an independent Worksheet and deletes it from the Project Map with DeleteNavigatorItems, first as a dry run that deletes nothing."""
import aclib

worksheet = aclib.RunTapirCommand ('CreateWorksheets', {
    'worksheetsData': [{'name': 'Tapir Example Worksheet', 'referenceId': 'TAPIR-W1'}]
})['databases'][0]

parameters = {
    'navigatorItemIds': [{'navigatorItemId': worksheet['navigatorItemId']}]
}
aclib.PrintJson (aclib.RunTapirCommand ('DeleteNavigatorItems', dict (parameters, dryRun = True)))
aclib.PrintJson (aclib.RunTapirCommand ('DeleteNavigatorItems', parameters))

"""Prints the folder each View Map view is in, with GetNavigatorParentItems."""
import aclib

def AllItems (item):
    for child in item.get ('children', []):
        yield child['navigatorItem']
        yield from AllItems (child['navigatorItem'])

viewMap = aclib.RunTapirCommand ('GetNavigatorItemTree', {'navigatorMapId': 'PublicViewMap'})['navigatorItemTree']
views = [item for item in AllItems (viewMap) if item['type'] != 'FolderItem']
if not views:
    raise SystemExit ('No view in the View Map.')

parents = aclib.RunTapirCommand ('GetNavigatorParentItems', {
    'navigatorItemIds': [{'navigatorItemId': view['navigatorItemId']} for view in views]
})['parentItems']

for view, parent in zip (views, parents):
    print (view['name'], '->', parent.get ('name', parent.get ('error')))

"""Creates an add-on viewpoint root with a leaf node in it, using CreateAddOnViewpoints.

The new items stay in the Project Map. Roots can't be created in a Teamwork project.
Requires Archicad 27 or later.
"""
import base64
import aclib

root = aclib.RunTapirCommand ('CreateAddOnViewpoints', {
    'viewpoints': [{'itemType': 'Root', 'displayId': 'TAPIR', 'displayName': 'Tapir Example Root'}]
})['viewpoints'][0]
aclib.PrintJson (root)

aclib.PrintJson (aclib.RunTapirCommand ('CreateAddOnViewpoints', {
    'viewpoints': [{
        'itemType': 'Leaf',
        'parentViewpointId': root['viewpointId'],
        'displayId': 'L1',
        'displayName': 'Tapir Example Leaf',
        'data': base64.b64encode (b'created by Tapir').decode ('ascii')
    }]
}))

"""Renames the first add-on viewpoint root with ChangeAddOnViewpoints, reads it back, then restores its name.

Needs an add-on viewpoint. Roots can't be changed in a Teamwork project. Requires Archicad 27 or later.
"""
import aclib

roots = aclib.RunTapirCommand ('GetAddOnViewpointRoots')['viewpointIds']
if not roots:
    raise SystemExit ('No add-on viewpoint in the project.')
root = aclib.RunTapirCommand ('GetAddOnViewpoints', {'viewpointIds': roots[:1]})['viewpoints'][0]

aclib.PrintJson (aclib.RunTapirCommand ('ChangeAddOnViewpoints', {
    'viewpoints': [{'viewpointId': root['viewpointId'], 'displayName': root['displayName'] + ' (Tapir)'}]
}))
aclib.RunTapirCommand ('GetAddOnViewpoints', {'viewpointIds': roots[:1]})

aclib.PrintJson (aclib.RunTapirCommand ('ChangeAddOnViewpoints', {
    'viewpoints': [{'viewpointId': root['viewpointId'], 'displayName': root['displayName']}]
}))

"""Creates a View Map folder with two subfolders and swaps their order with ReorderNavigatorItems.

Deletes the folders at the end.
"""
import aclib

parent = aclib.RunTapirCommand ('CreateViewMapFolder', {'folderName': 'Tapir Example Folder'})
first, second = [
    aclib.RunTapirCommand ('CreateViewMapFolder', {'folderName': name, 'parentNavigatorItemId': parent['navigatorItemId']})
    for name in ('Tapir A', 'Tapir B')
]

aclib.PrintJson (aclib.RunTapirCommand ('ReorderNavigatorItems', {
    'parentNavigatorItemId': parent['navigatorItemId'],
    'orderedNavigatorItemIds': [
        {'navigatorItemId': second['navigatorItemId']},
        {'navigatorItemId': first['navigatorItemId']}
    ]
}))

# A folder that is not empty cannot be deleted: delete the subfolders first.
aclib.RunTapirCommand ('DeleteNavigatorItems', {
    'navigatorItemIds': [{'navigatorItemId': first['navigatorItemId']}, {'navigatorItemId': second['navigatorItemId']}]
})
aclib.RunTapirCommand ('DeleteNavigatorItems', {'navigatorItemIds': [{'navigatorItemId': parent['navigatorItemId']}]})
